{"command":"cd /workspace && cat > internal/converter/escape.go <<'EOF'
package converter

import (
	"strings"
	"unicode"
)

// escapeText prepares a text node for the markdown output. Characters that
// could have a meaning in markdown get a marker in front of them, the decision
// whether a backslash is needed happens later (see resolveEscapes).
func escapeText(s string) string {
	var b strings.Builder
	b.Grow(len(s) + 8)
	for _, r := range s {
		switch r {
		case '\\', '`', '*', '_', '#', '+', '-', '=', '.', ')', '[', ']', '~', '|':
			b.WriteRune(markEscape)
			b.WriteRune(r)
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// forceEscapeBrackets turns marked brackets into escaped brackets. Used for
// the content of links.
func forceEscapeBrackets(s string) string {
	if !strings.ContainsRune(s, markEscape) {
		return s
	}
	s = strings.ReplaceAll(s, strEscape+"[", "\\[")
	s = strings.ReplaceAll(s, strEscape+"]", "\\]")
	return s
}

type escapeOptions struct {
	pipes         bool // inside of a table cell
	strikethrough bool // the strikethrough plugin is enabled
}

func isNewline(r rune) bool {
	return r == '\n' || r == markCodeNL
}

func isBlankRune(r rune) bool {
	return r == ' ' || r == '\t'
}

// resolveEscapes decides for every marked character whether it needs to be
// escaped with a backslash.
func resolveEscapes(s string, opt escapeOptions) string {
	if !strings.ContainsRune(s, markEscape) {
		return s
	}
	src := []rune(s)
	clean := make([]rune, 0, len(src))
	marked := make([]bool, 0, len(src))
	for i := 0; i < len(src); i++ {
		if src[i] == markEscape {
			if i+1 < len(src) && src[i+1] != markEscape {
				clean = append(clean, src[i+1])
				marked = append(marked, true)
				i++
			}
			continue
		}
		clean = append(clean, src[i])
		marked = append(marked, false)
	}

	r := &resolver{c: clean, m: marked, opt: opt}
	r.computeLines()

	var b strings.Builder
	b.Grow(len(s))
	for i, ch := range clean {
		if marked[i] && r.shouldEscape(i) {
			b.WriteByte('\\')
		}
		b.WriteRune(ch)
	}
	return b.String()
}

type resolver struct {
	c   []rune
	m   []bool
	opt escapeOptions

	lineStart []int // for every index, the index where its line starts
	lineEnd   []int // for every index, the index of the newline (or len)
}

func (r *resolver) computeLines() {
	n := len(r.c)
	r.lineStart = make([]int, n)
	r.lineEnd = make([]int, n)
	start := 0
	for i := 0; i <= n; i++ {
		if i == n || isNewline(r.c[i]) {
			for j := start; j < i; j++ {
				r.lineStart[j] = start
				r.lineEnd[j] = i
			}
			if i < n {
				r.lineStart[i] = start
				r.lineEnd[i] = i
			}
			start = i + 1
		}
	}
}

// atLineStart reports whether only blanks precede index i on its line.
func (r *resolver) atLineStart(i int) bool {
	for j := r.lineStart[i]; j < i; j++ {
		if !isBlankRune(r.c[j]) {
			return false
		}
	}
	return true
}

// firstContent returns the index of the first non blank char of the line.
func (r *resolver) firstContent(i int) int {
	j := r.lineStart[i]
	for j < r.lineEnd[i] && isBlankRune(r.c[j]) {
		j++
	}
	return j
}

func (r *resolver) hasNextNonSpace(i int) bool {
	if i+1 >= len(r.c) {
		return false
	}
	next := r.c[i+1]
	if isNewline(next) {
		return false
	}
	return !unicode.IsSpace(next)
}

// nextIsBlankOrEOL reports whether the char after index j is a blank, a
// newline or the end of the content.
func (r *resolver) nextIsBlankOrEOL(j int) bool {
	if j+1 >= len(r.c) {
		return true
	}
	next := r.c[j+1]
	return isBlankRune(next) || isNewline(next)
}

func (r *resolver) prevLineNonEmpty(i int) bool {
	ls := r.lineStart[i]
	if ls == 0 {
		return false
	}
	// ls-1 is the newline that ends the previous line
	prevStart := r.lineStart[ls-1]
	for j := prevStart; j < ls-1; j++ {
		if !unicode.IsSpace(r.c[j]) {
			return true
		}
	}
	return false
}

// isThematicBreak reports whether the line of index i only consists of
// at least three ch characters (and blanks).
func (r *resolver) isThematicBreak(i int, ch rune) bool {
	count := 0
	for j := r.lineStart[i]; j < r.lineEnd[i]; j++ {
		switch {
		case r.c[j] == ch:
			count++
		case isBlankRune(r.c[j]):
		default:
			return false
		}
	}
	return count >= 3
}

// runLength returns the number of consecutive ch starting at index i.
func (r *resolver) runLength(i int, ch rune) int {
	n := 0
	for j := i; j < len(r.c) && r.c[j] == ch; j++ {
		n++
	}
	return n
}

// insideFence reports whether the index i is part of a fence like sequence
// (at least three ch) at the start of the line, but not the first char of it.
func (r *resolver) fenceState(i int, ch rune) (isFirst bool, isInside bool) {
	start := r.firstContent(i)
	if start > i {
		return false, false
	}
	for j := start; j <= i; j++ {
		if r.c[j] != ch {
			return false, false
		}
	}
	if r.runLength(start, ch) < 3 {
		return false, false
	}
	if start == i {
		return true, false
	}
	return false, true
}

func (r *resolver) lineIsHeading(i int) bool {
	start := r.firstContent(i)
	if start != r.lineStart[i] {
		return false
	}
	j := start
	n := 0
	for j < r.lineEnd[i] && r.c[j] == '#' {
		if n == 0 && r.m[j] {
			return false
		}
		n++
		j++
	}
	if n == 0 || n > 6 {
		return false
	}
	if j < r.lineEnd[i] && !isBlankRune(r.c[j]) {
		return false
	}
	return true
}

func (r *resolver) isLastOnLine(i int) bool {
	for j := i + 1; j < r.lineEnd[i]; j++ {
		if !isBlankRune(r.c[j]) {
			return false
		}
	}
	return true
}

func (r *resolver) shouldEscape(i int) bool {
	ch := r.c[i]
	switch ch {
	case '\\':
		return true
	case '`':
		first, inside := r.fenceState(i, '`')
		if first {
			return true
		}
		if inside {
			return false
		}
		return true
	case '~':
		first, inside := r.fenceState(i, '~')
		if first {
			return true
		}
		if inside {
			return false
		}
		if r.opt.strikethrough {
			return r.hasNextNonSpace(i)
		}
		return false
	case '*':
		if r.hasNextNonSpace(i) {
			return true
		}
		if r.atLineStart(i) {
			if r.nextIsBlankOrEOL(i) {
				return true
			}
			if r.isThematicBreak(i, '*') {
				return true
			}
		}
		return false
	case '_':
		if r.hasNextNonSpace(i) {
			return true
		}
		if r.atLineStart(i) && r.isThematicBreak(i, '_') {
			return true
		}
		return false
	case '-':
		if !r.atLineStart(i) {
			return false
		}
		return r.nextIsBlankOrEOL(i) || r.prevLineNonEmpty(i) || r.isThematicBreak(i, '-')
	case '+':
		return r.atLineStart(i) && r.nextIsBlankOrEOL(i)
	case '=':
		return r.atLineStart(i) && r.prevLineNonEmpty(i)
	case '#':
		if r.atLineStart(i) {
			n := r.runLength(i, '#')
			if n > 6 {
				return false
			}
			return r.nextIsBlankOrEOL(i + n - 1)
		}
		return r.lineIsHeading(i) && r.isLastOnLine(i)
	case '.', ')':
		start := r.firstContent(i)
		if start >= i {
			return false
		}
		for j := start; j < i; j++ {
			if r.c[j] < '0' || r.c[j] > '9' {
				return false
			}
		}
		return r.nextIsBlankOrEOL(i)
	case '[':
		for j := i + 1; j < r.lineEnd[i]; j++ {
			if r.c[j] == ']' {
				return true
			}
		}
		return false
	case ']':
		return false
	case '|':
		return r.opt.pipes
	}
	return false
}
EOF
echo ok"}

