	case '=':
		return r.atLineStart(i) && r.prevLineNonEmpty(i)
	case '#':
		if r.atLineStart(i) {
			n := r.runLength(i, '#')
			if n > 6 {
				return false
			}
			return r.nextIsBlankOrEOL(i + n - 1)
		}
		return r.lineIsHeading(i) && r.isLastOnLine(i)
	case '.', ')':
		start := r.firstContent(i)
		if start >= i {
			return false
		}
		for j := start; j < i; j++ {
			if r.c[j] < '0' || r.c[j] > '9' {
				return false
			}
		}
		return r.nextIsBlankOrEOL(i)
	case '[':
		for j := i + 1; j < r.lineEnd[i]; j++ {
			if r.c[j] == ']' {
				return true
			}
		}
		return false
	case ']':
		return false
	case '|':
		return r.opt.pipes
	}
	return false
}
