	return n.Type == html.ElementNode && blockElements[n.Data]
}

func isVoidNode(n *html.Node) bool {
	return n.Type == html.ElementNode && voidElements[n.Data]
}

func isPreNode(n *html.Node) bool {
	return n.Type == html.ElementNode && (n.Data == "pre" || n.Data == "code")
}
