package converter

import (
	"regexp"
	"strings"

	"golang.org/x/net/html"
	"golang.org/x/net/html/atom"
)

var removedElements = map[string]bool{
	"head":     true,
	"script":   true,
	"style":    true,
	"noscript": true,
	"iframe":   true,
	"textarea": true,
	"input":    true,
}

func (c *conv) preprocess(doc *html.Node) {
	removeUnwanted(doc)
	swapTags(doc)
	leafBlockAlternatives(doc)
	fixLists(doc)
	removeEmptyCode(doc)
	collapseWhitespace(doc)
}

// removeUnwanted removes comments and elements that have no markdown
// representation (scripts, styles, ...).
func removeUnwanted(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		switch n.Type {
		case html.CommentNode, html.DoctypeNode:
			return true
		case html.ElementNode:
			return removedElements[n.Data]
		}
		return false
	})
	for _, n := range nodes {
		removeNodeFromParent(n)
	}
}

var codeLikeElements = map[string]bool{
	"code": true, "kbd": true, "samp": true, "tt": true, "var": true,
}

// onlyElementChild returns the single element child of n, if all other
// children are whitespace text or comments.
func onlyElementChild(n *html.Node) *html.Node {
	var found *html.Node
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case html.ElementNode:
			if found != nil {
				return nil
			}
			found = c
		case html.TextNode:
			if !isWhitespaceText(c) {
				return nil
			}
		case html.CommentNode:
		default:
			return nil
		}
	}
	return found
}

func swapElements(a, b *html.Node) {
	a.Data, b.Data = b.Data, a.Data
	a.DataAtom, b.DataAtom = b.DataAtom, a.DataAtom
	a.Attr, b.Attr = b.Attr, a.Attr
	a.Namespace, b.Namespace = b.Namespace, a.Namespace
}

// swapTags moves block elements outside of inline elements, for example
// <a><h1>title</h1></a> becomes <h1><a>title</a></h1>.
func swapTags(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		return n.Type == html.ElementNode && (n.Data == "a" || codeLikeElements[n.Data])
	})
	for _, n := range nodes {
		child := onlyElementChild(n)
		if child == nil {
			continue
		}
		if n.Data == "a" && isHeading(child) {
			swapElements(n, child)
		} else if codeLikeElements[n.Data] && child.Type == html.ElementNode && child.Data == "pre" {
			swapElements(n, child)
		}
	}
}

var inlineContextAtoms = []atom.Atom{
	atom.A, atom.B, atom.Strong, atom.I, atom.Em, atom.Code,
	atom.H1, atom.H2, atom.H3, atom.H4, atom.H5, atom.H6,
}

// leafBlockAlternatives replaces block elements that are inside of inline
// elements with an inline alternative.
func leafBlockAlternatives(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		if n.Type != html.ElementNode {
			return false
		}
		switch n.Data {
		case "h1", "h2", "h3", "h4", "h5", "h6", "pre", "hr", "blockquote", "ul", "ol", "li":
			return true
		}
		return false
	})
	for _, n := range nodes {
		if n.Parent == nil {
			continue
		}
		if !hasAncestor(n, inlineContextAtoms...) {
			continue
		}
		switch n.Data {
		case "h1", "h2", "h3", "h4", "h5", "h6":
			n.Data = "strong"
			n.DataAtom = 0
			n.Attr = nil
			br := &html.Node{Type: html.ElementNode, Data: "br", DataAtom: atom.Br}
			n.Parent.InsertBefore(br, n.NextSibling)
		case "pre":
			n.Data = "code"
			n.DataAtom = 0
		case "hr":
			removeNodeFromParent(n)
		case "blockquote":
			p := n.Parent
			p.InsertBefore(&html.Node{Type: html.TextNode, Data: ` "`}, n)
			p.InsertBefore(&html.Node{Type: html.TextNode, Data: `" `}, n.NextSibling)
			unwrapNode(n)
		case "ul", "ol", "li":
			unwrapNode(n)
		}
	}
}

// fixLists moves content that is directly inside of a list (and not inside
// of a list item) into a list item.
func fixLists(doc *html.Node) {
	lists := collectNodes(doc, func(n *html.Node) bool {
		return isElement(n, "ul", "ol")
	})
	for _, list := range lists {
		var lastItem *html.Node
		for c := list.FirstChild; c != nil; {
			next := c.NextSibling
			switch {
			case isElement(c, "li"):
				lastItem = c
			case c.Type == html.CommentNode:
			case c.Type == html.TextNode && isWhitespaceText(c):
			default:
				if lastItem == nil {
					lastItem = &html.Node{Type: html.ElementNode, Data: "li", DataAtom: atom.Li}
					list.InsertBefore(lastItem, c)
				}
				list.RemoveChild(c)
				lastItem.AppendChild(c)
			}
			c = next
		}
	}
}

func removeEmptyCode(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		return isOriginalElement(n, atom.Code)
	})
	for _, n := range nodes {
		if textContent(n) == "" {
			removeNodeFromParent(n)
		}
	}
}

var whitespaceRun = regexp.MustCompile(`[ \r\n\t]+`)

// collapseWhitespace collapses the whitespace like a browser would do.
func collapseWhitespace(root *html.Node) {
	if root.FirstChild == nil || isPreNode(root) {
		return
	}
	var prevText *html.Node
	keepLeadingWs := false

	var prev *html.Node
	node := nextCollapseNode(prev, root)
	for node != root && node != nil {
		if node.Type == html.TextNode {
			text := whitespaceRun.ReplaceAllString(node.Data, " ")
			if (prevText == nil || strings.HasSuffix(prevText.Data, " ")) &&
				!keepLeadingWs && strings.HasPrefix(text, " ") {
				text = text[1:]
			}
			if text == "" {
				node = removeAndNext(node)
				continue
			}
			node.Data = text
			prevText = node
		} else if node.Type == html.ElementNode {
			if isBlockNode(node) || node.Data == "br" {
				if prevText != nil {
					prevText.Data = strings.TrimSuffix(prevText.Data, " ")
				}
				prevText = nil
				keepLeadingWs = false
			} else if isVoidNode(node) || isPreNode(node) {
				prevText = nil
				keepLeadingWs = true
			} else if prevText != nil {
				keepLeadingWs = false
			}
		} else {
			node = removeAndNext(node)
			continue
		}
		nextNode := nextCollapseNode(prev, node)
		prev = node
		node = nextNode
	}
	if prevText != nil {
		prevText.Data = strings.TrimSuffix(prevText.Data, " ")
		if prevText.Data == "" {
			removeNodeFromParent(prevText)
		}
	}
}

func removeAndNext(n *html.Node) *html.Node {
	next := n.NextSibling
	if next == nil {
		next = n.Parent
	}
	removeNodeFromParent(n)
	return next
}

func nextCollapseNode(prev, current *html.Node) *html.Node {
	if (prev != nil && prev.Parent == current) || isPreNode(current) {
		if current.NextSibling != nil {
			return current.NextSibling
		}
		return current.Parent
	}
	if current.FirstChild != nil {
		return current.FirstChild
	}
	if current.NextSibling != nil {
		return current.NextSibling
	}
	return current.Parent
}
EOF
echo ok"}

