// removeUnwanted removes comments and elements that have no markdown
// representation (scripts, styles, ...).
func removeUnwanted(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		switch n.Type {
		case html.CommentNode, html.DoctypeNode:
			return true
		case html.ElementNode:
			return removedElements[n.Data]
		}
		return false
	})
	for _, n := range nodes {
		removeNodeFromParent(n)
	}
}

var codeLikeElements = map[string]bool{
	"code": true, "kbd": true, "samp": true, "tt": true, "var": true,
}

// onlyElementChild returns the single element child of n, if all other
// children are whitespace text or comments.
func onlyElementChild(n *html.Node) *html.Node {
	var found *html.Node
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case html.ElementNode:
			if found != nil {
				return nil
			}
			found = c
		case html.TextNode:
			if !isWhitespaceText(c) {
				return nil
			}
		case html.CommentNode:
		default:
			return nil
		}
	}
	return found
}

func swapElements(a, b *html.Node) {
	a.Data, b.Data = b.Data, a.Data
	a.DataAtom, b.DataAtom = b.DataAtom, a.DataAtom
	a.Attr, b.Attr = b.Attr, a.Attr
	a.Namespace, b.Namespace = b.Namespace, a.Namespace
}

// swapTags moves block elements outside of inline elements, for example
// <a><h1>title</h1></a> becomes <h1><a>title</a></h1>.
func swapTags(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		return n.Type == html.ElementNode && (n.Data == "a" || codeLikeElements[n.Data])
	})
	for _, n := range nodes {
		child := onlyElementChild(n)
		if child == nil {
			continue
		}
		if n.Data == "a" && isHeading(child) {
			swapElements(n, child)
		} else if codeLikeElements[n.Data] && child.Type == html.ElementNode && child.Data == "pre" {
			swapElements(n, child)
		}
	}
}

var inlineContextAtoms = []atom.Atom{
	atom.A, atom.B, atom.Strong, atom.I, atom.Em, atom.Code,
	atom.H1, atom.H2, atom.H3, atom.H4, atom.H5, atom.H6,
