					list.InsertBefore(lastItem, c)
				}
				list.RemoveChild(c)
				lastItem.AppendChild(c)
			}
			c = next
		}
	}
}

func removeEmptyCode(doc *html.Node) {
	nodes := collectNodes(doc, func(n *html.Node) bool {
		return isOriginalElement(n, atom.Code)
	})
	for _, n := range nodes {
		if textContent(n) == "" {
			removeNodeFromParent(n)
		}
