)

func (c *conv) renderChildren(w *strings.Builder, n *html.Node) {
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		c.render(w, ch)
	}
}

func (c *conv) renderChildrenString(n *html.Node) string {
	var b strings.Builder
	c.renderChildren(&b, n)
	return b.String()
}

func (c *conv) render(w *strings.Builder, n *html.Node) {
	if c.skip[n] {
		return
	}
	switch n.Type {
	case html.TextNode:
		w.WriteString(escapeText(n.Data))
		return
	case html.DocumentNode:
		c.renderChildren(w, n)
		return
	case html.ElementNode:
	default:
		return
	}

	switch n.Data {
	case "h1", "h2", "h3", "h4", "h5", "h6":
		if n.DataAtom != 0 {
			c.renderHeading(w, n)
			return
		}
	case "p", "div", "section", "article", "header", "footer", "nav", "aside",
		"main", "address", "details", "form", "dl", "dt", "dd", "figure",
		"figcaption", "fieldset", "hgroup", "dialog", "li":
		c.renderBlock(w, n)
		return
	case "blockquote":
		c.renderBlockquote(w, n)
		return
	case "pre":
		c.renderCodeBlock(w, n)
		return
	case "code", "kbd", "samp", "tt", "var":
		c.renderInlineCode(w, n)
		return
	case "b", "strong":
		c.renderEmphasis(w, n, kindBold)
		return
	case "i", "em":
		c.renderEmphasis(w, n, kindItalic)
		return
	case "del", "s", "strike":
		if c.opt.Strikethrough {
			c.renderEmphasis(w, n, kindStrike)
			return
		}
	case "a":
		c.renderLink(w, n)
		return
	case "img":
		c.renderImage(w, n)
		return
	case "br":
		w.WriteString(strBreak + "\n")
		return
	case "hr":
		w.WriteString("\n\n* * *\n\n")
		return
	case "ul", "ol":
		c.renderList(w, n)
		return
	case "table":
		if c.opt.Table != nil && c.renderTable(w, n) {
			return
		}
		c.renderBlock(w, n)
		return
	}
	c.renderChildren(w, n)
}

func (c *conv) renderBlock(w *strings.Builder, n *html.Node) {
	w.WriteString("\n\n")
	c.renderChildren(w, n)
	w.WriteString("\n\n")
}

// singleLine joins all lines of the content with a space.
func singleLine(s string) string {
	s = strings.ReplaceAll(s, strCodeNL, "\n")
	lines := strings.Split(s, "\n")
	parts := make([]string, 0, len(lines))
	for _, line := range lines {
		line = trimSpaceLike(line)
		if line != "" {
			parts = append(parts, line)
		}
	}
	return strings.Join(parts, " ")
}

func (c *conv) renderHeading(w *strings.Builder, n *html.Node) {
	content := c.renderChildrenString(n)
	content = strings.ReplaceAll(content, strListEnd, "")
	content = singleLine(content)
	if content == "" {
		return
	}
	w.WriteString("\n\n")
	w.WriteString(strings.Repeat("#", headingLevel(n)))
	w.WriteString(" ")
	w.WriteString(content)
	w.WriteString("\n\n")
}

func (c *conv) renderBlockquote(w *strings.Builder, n *html.Node) {
	content := c.renderChildrenString(n)
	content = normalizeContent(content)
	if content == "" {
		return
	}
	content = breaksToSpaces(content)
	w.WriteString("\n\n")
	w.WriteString(prefixLines(content, "> "))
	w.WriteString("\n\n")
}

// codeText returns the text of a code element.
func codeText(n *html.Node) string {
	var b strings.Builder
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			switch ch.Type {
			case html.TextNode:
				b.WriteString(ch.Data)
			case html.ElementNode:
				switch ch.Data {
				case "br":
					b.WriteString("\n")
				case "div":
					b.WriteString("\n")
					walk(ch)
				default:
					walk(ch)
				}
			}
		}
	}
	walk(n)
	return b.String()
}

func longestRun(s string, ch byte) int {
	max, cur := 0, 0
	for i := 0; i < len(s); i++ {
		if s[i] == ch {
			cur++
			if cur > max {
				max = cur
			}
		} else {
			cur = 0
		}
	}
	return max
}

var codeWhitespace = " \t\r\n\f"

func collapseCodeWhitespace(s string) string {
	var b strings.Builder
	inSpace := false
	for _, r := range s {
		if strings.ContainsRune(codeWhitespace, r) {
			inSpace = true
			continue
		}
		if inSpace && b.Len() > 0 {
			b.WriteByte(' ')
		}
		inSpace = false
		b.WriteRune(r)
	}
	return b.String()
}

func (c *conv) renderInlineCode(w *strings.Builder, n *html.Node) {
	content := codeText(n)
	if strings.Trim(content, codeWhitespace) != "" {
		content = collapseCodeWhitespace(content)
	}
	fence := strings.Repeat("`", longestRun(content, '`')+1)
	if strings.HasPrefix(content, "`") {
		content = " " + content
	}
	if strings.HasSuffix(content, "`") {
		content = content + " "
	}
	w.WriteString(fence)
	w.WriteString(content)
	w.WriteString(fence)
}

func languageFromClass(n *html.Node) string {
	class := attrVal(n, "class")
	for _, part := range strings.Fields(class) {
		if strings.HasPrefix(part, "language-") {
			return strings.TrimPrefix(part, "language-")
		}
		if strings.HasPrefix(part, "lang-") {
			return strings.TrimPrefix(part, "lang-")
		}
	}
	return ""
}

func (c *conv) codeBlockLanguage(n *html.Node) string {
	if lang := languageFromClass(n); lang != "" {
		return lang
	}
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		if ch.Type == html.ElementNode && ch.Data == "code" {
			if lang := languageFromClass(ch); lang != "" {
				return lang
			}
		}
	}
	return ""
}

func (c *conv) renderCodeBlock(w *strings.Builder, n *html.Node) {
	content := codeText(n)
	lang := c.codeBlockLanguage(n)

	fenceLen := 3
	if run := longestRun(content, '`'); run >= 3 {
		fenceLen = run + 1
	}
	fence := strings.Repeat("`", fenceLen)

	content = strings.TrimSuffix(content, "\n")
	content = strings.ReplaceAll(content, "\n", strCodeNL)

	w.WriteString("\n\n")
	w.WriteString(fence)
	w.WriteString(lang)
	w.WriteString("\n")
	w.WriteString(content)
	w.WriteString("\n")
	w.WriteString(fence)
	w.WriteString("\n\n")
}

type emphasisKind int

const (
	kindBold emphasisKind = iota
	kindItalic
	kindStrike
)

func (k emphasisKind) atoms() []atom.Atom {
	switch k {
	case kindBold:
		return []atom.Atom{atom.B, atom.Strong}
	case kindItalic:
		return []atom.Atom{atom.I, atom.Em}
	}
	return []atom.Atom{atom.Del, atom.S, atom.Strike}
}

func (k emphasisKind) family() []atom.Atom {
	if k == kindStrike {
		return []atom.Atom{atom.Del, atom.S, atom.Strike}
	}
	return []atom.Atom{atom.B, atom.Strong, atom.I, atom.Em}
}

func kindOf(n *html.Node) emphasisKind {
	switch n.DataAtom {
	case atom.B, atom.Strong:
		return kindBold
	case atom.I, atom.Em:
		return kindItalic
	}
	return kindStrike
}

func (c *conv) delimiter(k emphasisKind) string {
	switch k {
	case kindBold:
		return c.opt.StrongDelimiter
	case kindItalic:
		return "*"
	}
	return "~~"
}

// absorbables returns the following sibling emphasis elements that should be
// merged into the emphasis node n.
func (c *conv) absorbables(n *html.Node, k emphasisKind) []*html.Node {
	var out []*html.Node
	family := k.family()
	var walk func(first *html.Node) bool
	walk = func(first *html.Node) bool {
		for s := first; s != nil; s = s.NextSibling {
			switch {
			case s.Type == html.CommentNode:
				continue
			case isOriginalElement(s, family...):
				if hasAncestor(s, kindOf(s).atoms()...) {
					return false
				}
				out = append(out, s)
			case isOriginalElement(s, atom.Span):
				if !walk(s.FirstChild) {
					return false
				}
			default:
				return false
			}
		}
		return true
	}
	walk(n.NextSibling)
	return out
}

func (c *conv) renderEmphasis(w *strings.Builder, n *html.Node, k emphasisKind) {
	original := n.DataAtom != 0
	if original && hasAncestor(n, k.atoms()...) {
		c.renderChildren(w, n)
		return
	}
	var buf strings.Builder
	c.renderChildren(&buf, n)
	if original {
		for _, m := range c.absorbables(n, k) {
			c.renderChildren(&buf, m)
			c.skip[m] = true
		}
	}
	writeDelimited(w, buf.String(), c.delimiter(k))
}

func writeDelimited(w *strings.Builder, content string, delim string) {
	if content == "" {
		return
	}
	if isBlankString(content) {
		w.WriteString(content)
		return
	}
	lines := strings.Split(content, "\n")
	for i, line := range lines {
		if i > 0 {
			w.WriteString("\n")
		}
		lead, mid, trail := splitSurroundingSpace(line)
		if mid == "" {
			w.WriteString(line)
			continue
		}
		w.WriteString(lead)
		w.WriteString(delim)
		w.WriteString(mid)
		w.WriteString(delim)
		w.WriteString(trail)
	}
}

func formatTitle(t string) string {
	if t == "" {
		return ""
	}
	t = strings.ReplaceAll(t, "\n", " ")
	if strings.Contains(t, `"`) {
		if !strings.Contains(t, "'") {
			return " '" + t + "'"
		}
		t = strings.ReplaceAll(t, `"`, `\"`)
	}
	return ` "` + t + `"`
}

