	w.WriteString(mid)
	w.WriteString("](")
	w.WriteString(href)
	w.WriteString(title)
	w.WriteString(")")
	w.WriteString(trail)
}

func (c *conv) renderImage(w *strings.Builder, n *html.Node) {
	src := strings.TrimSpace(attrVal(n, "src"))
	if src == "" {
		return
	}
	alt := attrVal(n, "alt")
	alt = strings.ReplaceAll(alt, "\n", " ")
	alt = strings.ReplaceAll(alt, "[", "\\[")
	alt = strings.ReplaceAll(alt, "]", "\\]")
