// parseDomain parses the --domain value, a missing scheme defaults to http.
func parseDomain(raw string) *url.URL {
	if raw == "" {
		return nil
	}
	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Host == "" {
		u, err = url.Parse("http://" + raw)
		if err != nil {
			return nil
		}
	}
	if u.Host == "" {
		return nil
	}
	return u
}

func encodeQueryPart(s string) string {
	if dec, err := url.QueryUnescape(s); err == nil {
		s = url.QueryEscape(dec)
	}
	return strings.ReplaceAll(s, "+", "%20")
}

func encodeQuery(q string) string {
	if q == "" {
		return q
	}
	parts := strings.Split(q, "&")
	for i, p := range parts {
		k, v, hasEq := strings.Cut(p, "=")
		if hasEq {
			parts[i] = encodeQueryPart(k) + "=" + encodeQueryPart(v)
		} else {
			parts[i] = encodeQueryPart(k)
		}
	}
	return strings.Join(parts, "&")
}

func (c *conv) processURL(raw string) string {
	raw = strings.TrimSpace(raw)
	u, err := url.Parse(raw)
	if err != nil {
		return urlReplacer.Replace(raw)
	}
	if c.base != nil {
		u = c.base.ResolveReference(u)
	}
	u.RawQuery = encodeQuery(u.RawQuery)
	s := u.String()
	if s == "" {
		s = raw
	}
	return urlReplacer.Replace(s)
