package converter

import (
	"bytes"
	"net/url"
	"strings"

	"golang.org/x/net/html"
)

// TableOptions configures the table plugin.
type TableOptions struct {
	HeaderPromotion    bool
	PresentationTables bool
	SkipEmptyRows      bool
	CellPadding        string // aligned, minimal, none
	NewlineBehavior    string // skip, preserve
	SpanCellBehavior   string // empty, mirror
}

// Options configures the conversion.
type Options struct {
	StrongDelimiter string
	Domain          string
	Strikethrough   bool
	Table           *TableOptions

	// Filter is called with the parsed document before anything else.
	Filter func(doc *html.Node) *html.Node
}

type conv struct {
	opt  Options
	base *url.URL
	skip map[*html.Node]bool
}

// Convert converts html into markdown.
func Convert(input []byte, opt Options) (string, error) {
	if opt.StrongDelimiter == "" {
		opt.StrongDelimiter = "**"
	}
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return "", err
	}
	if opt.Filter != nil {
		doc = opt.Filter(doc)
	}
	c := &conv{
		opt:  opt,
		base: parseDomain(opt.Domain),
		skip: map[*html.Node]bool{},
	}
	c.preprocess(doc)

	var w strings.Builder
	c.render(&w, doc)

	out := w.String()
	out = strings.ReplaceAll(out, strListEnd, "")
	out = normalizeContent(out)
	out = breaksToSpaces(out)
	out = resolveEscapes(out, escapeOptions{strikethrough: opt.Strikethrough})
	out = finalizeMarkers(out)
	return out, nil
}
