// Package glob implements file globbing with support for "**" (any number
// of directories), "*", "?", character classes and {alternatives}.
package glob

import (
	"errors"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// ErrBadPattern is returned for malformed patterns.
var ErrBadPattern = errors.New("syntax error in pattern")

// Match is a single file that matched the pattern.
type Match struct {
	Path string // the path that can be used to open the file
	Rel  string // the path relative to the base directory of the pattern
}

func isMeta(c byte) bool {
	return c == '*' || c == '?' || c == '[' || c == '{' || c == '\\'
}

// indexMeta returns the index of the first meta character.
func indexMeta(s string) int {
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '*', '?', '[', '{':
			return i
		case '\\':
			if i+1 < len(s) {
				i++
			}
		}
	}
	return -1
}

func hasMeta(s string) bool {
	return indexMeta(s) != -1
}

func unescape(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// Validate checks the syntax of the pattern.
func Validate(pattern string) error {
	depth := 0
	for i := 0; i < len(pattern); i++ {
		switch pattern[i] {
		case '\\':
			if i+1 >= len(pattern) {
				return ErrBadPattern
			}
			i++
		case '[':
			j := i + 1
			if j < len(pattern) && (pattern[j] == '!' || pattern[j] == '^') {
				j++
			}
			if j < len(pattern) && pattern[j] == ']' {
				j++
			}
			closed := false
			for ; j < len(pattern); j++ {
				if pattern[j] == '\\' {
					j++
					continue
				}
				if pattern[j] == '/' {
					break
				}
				if pattern[j] == ']' {
					closed = true
					break
				}
			}
			if !closed {
				return ErrBadPattern
			}
			i = j
		case '{':
			depth++
		case '}':
			if depth > 0 {
				depth--
			}
		}
	}
	if depth != 0 {
		return ErrBadPattern
	}
	return nil
}

// SplitPattern splits the pattern into a base path and the pattern relative
// to that base.
func SplitPattern(p string) (string, string) {
	idx := indexMeta(p)
	if idx == -1 {
		idx = len(p)
	}
	slash := strings.LastIndexByte(p[:idx], '/')
	if slash == -1 {
		return ".", p
	}
	if slash == 0 {
		return "/", p[1:]
	}
	return p[:slash], p[slash+1:]
}

// Glob returns all files that match the pattern.
func Glob(pattern string) ([]Match, error) {
	if err := Validate(pattern); err != nil {
		return nil, err
	}
	base, rel := SplitPattern(pattern)
	if !hasMeta(rel) {
		p := unescape(pattern)
		info, err := os.Stat(p)
		if err != nil || info.IsDir() {
			return nil, nil
		}
		return []Match{{Path: p, Rel: path.Base(p)}}, nil
	}
	g := &globber{base: base}
	var out []Match
	seen := map[string]bool{}
	for _, pat := range expandSlashBraces(rel) {
		for _, r := range g.glob(pat, true) {
			if seen[r] {
				continue
			}
			seen[r] = true
			out = append(out, Match{Path: filepath.Join(base, filepath.FromSlash(r)), Rel: r})
		}
	}
	return out, nil
}

type globber struct {
	base string
}

func (g *globber) full(rel string) string {
	return filepath.Join(g.base, filepath.FromSlash(rel))
}

func joinRel(dir, name string) string {
	if dir == "." || dir == "" {
		return name
	}
	return dir + "/" + name
}

type entry struct {
	name  string
	isDir bool
}

func (g *globber) readDir(dir string) []entry {
	des, err := os.ReadDir(g.full(dir))
	if err != nil {
		return nil
	}
	sort.Slice(des, func(i, j int) bool { return des[i].Name() < des[j].Name() })
	out := make([]entry, 0, len(des))
	for _, de := range des {
		isDir := de.IsDir()
		if de.Type()&fs.ModeSymlink != 0 {
			if info, err := os.Stat(g.full(joinRel(dir, de.Name()))); err == nil {
				isDir = info.IsDir()
			}
		}
		out = append(out, entry{name: de.Name(), isDir: isDir})
	}
	return out
}

// lastSlash returns the index of the last slash that is not escaped and not
// inside of braces or brackets.
func lastSlash(p string) int {
	last := -1
	depth := 0
	inClass := false
	for i := 0; i < len(p); i++ {
		switch c := p[i]; {
		case c == '\\':
			i++
		case inClass:
			if c == ']' {
				inClass = false
			}
		case c == '[':
			inClass = true
		case c == '{':
			depth++
		case c == '}':
			if depth > 0 {
				depth--
			}
		case c == '/' && depth == 0:
			last = i
		}
	}
	return last
}

// glob returns the relative paths matching the pattern. If wantFiles is
// false, only directories are returned.
func (g *globber) glob(pattern string, wantFiles bool) []string {
	var dirs []string
	last := pattern
	if idx := lastSlash(pattern); idx != -1 {
		dirPattern := pattern[:idx]
		last = pattern[idx+1:]
		if hasMeta(dirPattern) {
			dirs = g.glob(dirPattern, false)
		} else {
			d := unescape(dirPattern)
			if info, err := os.Stat(g.full(d)); err == nil && info.IsDir() {
				dirs = []string{d}
			}
		}
	} else {
		dirs = []string{"."}
	}

	var out []string
	for _, dir := range dirs {
		switch {
		case last == "**":
			if wantFiles {
				out = g.doubleStarFiles(dir, out)
			} else {
				out = append(out, dir)
				out = g.doubleStarDirs(dir, out)
			}
		case !hasMeta(last):
			name := unescape(last)
			p := joinRel(dir, name)
			if info, err := os.Stat(g.full(p)); err == nil && info.IsDir() != wantFiles {
				out = append(out, p)
			}
		default:
			for _, e := range g.readDir(dir) {
				if e.isDir == wantFiles {
					continue
				}
				if matchSegment(last, e.name) {
					out = append(out, joinRel(dir, e.name))
				}
			}
		}
	}
	return out
}

func (g *globber) doubleStarFiles(dir string, out []string) []string {
	for _, e := range g.readDir(dir) {
		p := joinRel(dir, e.name)
		if e.isDir {
			out = g.doubleStarFiles(p, out)
		} else {
			out = append(out, p)
		}
	}
	return out
}

func (g *globber) doubleStarDirs(dir string, out []string) []string {
	for _, e := range g.readDir(dir) {
		if !e.isDir {
			continue
		}
		p := joinRel(dir, e.name)
		out = append(out, p)
		out = g.doubleStarDirs(p, out)
	}
	return out
}

// expandSlashBraces expands alternatives that contain a slash, so that the
// remaining patterns only have alternatives inside of single segments.
func expandSlashBraces(p string) []string {
	start := -1
	depth := 0
	for i := 0; i < len(p); i++ {
		switch p[i] {
		case '\\':
			i++
		case '{':
			if depth == 0 {
				start = i
			}
			depth++
		case '}':
			if depth > 0 {
				depth--
				if depth == 0 {
					inner := p[start+1 : i]
					if strings.Contains(inner, "/") {
						var out []string
						for _, alt := range splitAlternatives(inner) {
							out = append(out, expandSlashBraces(p[:start]+alt+p[i+1:])...)
						}
						return out
					}
				}
			}
		}
	}
	return []string{p}
}

func splitAlternatives(s string) []string {
	var out []string
	depth := 0
	last := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\\':
			i++
		case '{':
			depth++
		case '}':
			depth--
		case ',':
			if depth == 0 {
				out = append(out, s[last:i])
				last = i + 1
			}
		}
	}
	return append(out, s[last:])
}

// matchSegment matches a single path segment against the pattern.
func matchSegment(pattern, name string) bool {
	return matchHere(pattern, name)
}

func matchHere(p, s string) bool {
	for len(p) > 0 {
		switch p[0] {
		case '*':
			// collapse multiple stars
			for len(p) > 0 && p[0] == '*' {
				p = p[1:]
			}
			if len(p) == 0 {
				return true
			}
			for i := 0; i <= len(s); i++ {
				if matchHere(p, s[i:]) {
					return true
				}
			}
			return false
		case '?':
			if len(s) == 0 {
				return false
			}
			_, size := decodeRune(s)
			p = p[1:]
			s = s[size:]
		case '[':
			if len(s) == 0 {
				return false
			}
			r, size := decodeRune(s)
			ok, rest, valid := matchClass(p, r)
			if !valid || !ok {
				return false
			}
			p = rest
			s = s[size:]
		case '{':
			end := closingBrace(p)
			if end == -1 {
				return false
			}
			rest := p[end+1:]
			for _, alt := range splitAlternatives(p[1:end]) {
				if matchHere(alt+rest, s) {
					return true
				}
			}
			return false
		case '\\':
			if len(p) < 2 {
				return false
			}
			if len(s) == 0 || s[0] != p[1] {
				return false
			}
			p = p[2:]
			s = s[1:]
		default:
			if len(s) == 0 || s[0] != p[0] {
				return false
			}
			p = p[1:]
			s = s[1:]
		}
	}
	return len(s) == 0
}

func closingBrace(p string) int {
	depth := 0
	for i := 0; i < len(p); i++ {
		switch p[i] {
		case '\\':
			i++
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return i
			}
		}
	}
	return -1
}

func decodeRune(s string) (rune, int) {
	for i, r := range s {
		_ = i
		return r, len(string(r))
	}
	return 0, 0
}

// matchClass matches a [...] class at the start of p.
func matchClass(p string, r rune) (matched bool, rest string, valid bool) {
	i := 1
	negate := false
	if i < len(p) && (p[i] == '!' || p[i] == '^') {
		negate = true
		i++
	}
	first := true
	for i < len(p) {
		if p[i] == ']' && !first {
			return matched != negate, p[i+1:], true
		}
		first = false
		lo, n := classChar(p[i:])
		if n == 0 {
			return false, "", false
		}
		i += n
		hi := lo
		if i+1 < len(p) && p[i] == '-' && p[i+1] != ']' {
			var n2 int
			hi, n2 = classChar(p[i+1:])
			if n2 == 0 {
				return false, "", false
			}
			i += 1 + n2
		}
		if lo <= r && r <= hi {
			matched = true
		}
	}
	return false, "", false
}

func classChar(p string) (rune, int) {
	if len(p) == 0 {
		return 0, 0
	}
	if p[0] == '\\' {
		if len(p) < 2 {
			return 0, 0
		}
		r, size := decodeRune(p[1:])
		return r, 1 + size
	}
	r, size := decodeRune(p)
	return r, size
}
