// Package cli implements the command line interface of html2markdown.
package cli

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/net/html"

	"html2markdown/internal/converter"
	"html2markdown/internal/glob"
	"html2markdown/internal/selector"
)

//go:embed help.txt
var helpText string

const versionText = "html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown\n"

const hintCLI = "Here is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n"
const hintGlob = "Here is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\"\n"
const hintOutputDir = "The --output must end with \"/\" to indicate a directory\n"

type cliError struct {
	msg  string
	hint string
}

func (e *cliError) Error() string { return e.msg }

func newErr(hint string, format string, args ...any) error {
	return &cliError{msg: fmt.Sprintf(format, args...), hint: hint}
}

// onceValue is a string flag that can only be set once and must not be empty.
type onceValue struct {
	value string
	isSet bool
}

func (v *onceValue) String() string { return v.value }
func (v *onceValue) Set(s string) error {
	if v.isSet {
		return errors.New("another value has already been set")
	}
	if s == "" {
		return errors.New("empty string")
	}
	v.value = s
	v.isSet = true
	return nil
}

type selectorList struct {
	selectors []selector.Selector
}

func (v *selectorList) String() string { return "" }
func (v *selectorList) Set(s string) error {
	if strings.TrimSpace(s) == "" {
		return errors.New("invalid css selector: empty string")
	}
	sel, err := selector.Parse(s)
	if err != nil {
		return fmt.Errorf("invalid css selector: %w", err)
	}
	v.selectors = append(v.selectors, sel)
	return nil
}

type config struct {
	version         bool
	input           onceValue
	output          onceValue
	outputOverwrite bool

	domain          string
	excludeSelector selectorList
	includeSelector selectorList

	strongDelimiter string

	tableCellPadding        string
	tableHeaderPromotion    bool
	tableNewlineBehavior    string
	tablePresentationTables bool
	tableSkipEmptyRows      bool
	tableSpanCellBehavior   string

	pluginStrikethrough bool
	pluginTable         bool
}

// Run executes the cli and returns the exit code.
func Run(args []string, stdin *os.File, stdout, stderr io.Writer) int {
	err := run(args, stdin, stdout)
	if err == nil {
		return 0
	}
	if errors.Is(err, flag.ErrHelp) {
		fmt.Fprint(stdout, helpText)
		return 0
	}
	fmt.Fprintf(stderr, "\nerror: %s\n\n", err.Error())
	var ce *cliError
	if errors.As(err, &ce) && ce.hint != "" {
		fmt.Fprintf(stderr, "%s\n", ce.hint)
	}
	return 1
}

func run(args []string, stdin *os.File, stdout io.Writer) error {
	cfg := &config{}
	fs := flag.NewFlagSet("html2markdown", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}

	fs.BoolVar(&cfg.version, "v", false, "")
	fs.BoolVar(&cfg.version, "version", false, "")
	fs.Var(&cfg.input, "input", "")
	fs.Var(&cfg.output, "output", "")
	fs.BoolVar(&cfg.outputOverwrite, "output-overwrite", false, "")
	fs.StringVar(&cfg.domain, "domain", "", "")
	fs.Var(&cfg.excludeSelector, "exclude-selector", "")
	fs.Var(&cfg.includeSelector, "include-selector", "")
	fs.StringVar(&cfg.strongDelimiter, "opt-strong-delimiter", "", "")
	fs.StringVar(&cfg.tableCellPadding, "opt-table-cell-padding-behavior", "", "")
	fs.BoolVar(&cfg.tableHeaderPromotion, "opt-table-header-promotion", false, "")
	fs.StringVar(&cfg.tableNewlineBehavior, "opt-table-newline-behavior", "", "")
	fs.BoolVar(&cfg.tablePresentationTables, "opt-table-presentation-tables", false, "")
	fs.BoolVar(&cfg.tableSkipEmptyRows, "opt-table-skip-empty-rows", false, "")
	fs.StringVar(&cfg.tableSpanCellBehavior, "opt-table-span-cell-behavior", "", "")
	fs.BoolVar(&cfg.pluginStrikethrough, "plugin-strikethrough", false, "")
	fs.BoolVar(&cfg.pluginTable, "plugin-table", false, "")

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return err
		}
		msg := err.Error()
		if strings.HasPrefix(msg, "flag provided but not defined: ") {
			msg = "unknown flag: " + strings.TrimPrefix(msg, "flag provided but not defined: ")
		}
		return errors.New(msg)
	}
	if rest := fs.Args(); len(rest) > 0 {
		return newErr(hintCLI, "unknown arguments: %s", strings.Join(rest, " "))
	}
	if cfg.version {
		fmt.Fprint(stdout, versionText)
		return nil
	}
	if !cfg.pluginTable {
		checks := []struct {
			name  string
			isSet bool
		}{
			{"--opt-table-skip-empty-rows", cfg.tableSkipEmptyRows},
			{"--opt-table-header-promotion", cfg.tableHeaderPromotion},
			{"--opt-table-span-cell-behavior", cfg.tableSpanCellBehavior != ""},
			{"--opt-table-presentation-tables", cfg.tablePresentationTables},
			{"--opt-table-newline-behavior", cfg.tableNewlineBehavior != ""},
			{"--opt-table-cell-padding-behavior", cfg.tableCellPadding != ""},
		}
		for _, c := range checks {
			if c.isSet {
				return fmt.Errorf("%s requires --plugin-table to be enabled", c.name)
			}
		}
	}

	inputs, err := resolveInputs(cfg, stdin)
	if err != nil {
		return err
	}
	if err := checkOutput(cfg, inputs); err != nil {
		return err
	}

	opts := converter.Options{
		Domain:        cfg.domain,
		Strikethrough: cfg.pluginStrikethrough,
	}
	if cfg.pluginTable {
		t := &converter.TableOptions{
			HeaderPromotion:    cfg.tableHeaderPromotion,
			PresentationTables: cfg.tablePresentationTables,
			SkipEmptyRows:      cfg.tableSkipEmptyRows,
			CellPadding:        cfg.tableCellPadding,
			NewlineBehavior:    cfg.tableNewlineBehavior,
			SpanCellBehavior:   cfg.tableSpanCellBehavior,
		}
		switch t.SpanCellBehavior {
		case "", "empty", "mirror":
		default:
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for span cell behavior", t.SpanCellBehavior)
		}
		switch t.NewlineBehavior {
		case "", "skip", "preserve":
		default:
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for newline behavior", t.NewlineBehavior)
		}
		switch t.CellPadding {
		case "", "aligned", "minimal", "none":
		default:
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for cell padding behavior", t.CellPadding)
		}
		opts.Table = t
	}
	switch cfg.strongDelimiter {
	case "", "**", "__":
		opts.StrongDelimiter = cfg.strongDelimiter
	default:
		return fmt.Errorf("invalid value for --opt-strong-delimiter=%q must be exactly 2 characters of \"**\" or \"__\"", cfg.strongDelimiter)
	}
	if len(cfg.excludeSelector.selectors) > 0 || len(cfg.includeSelector.selectors) > 0 {
		exclude := cfg.excludeSelector.selectors
		include := cfg.includeSelector.selectors
		opts.Filter = func(doc *html.Node) *html.Node {
			return filterDocument(doc, exclude, include)
		}
	}

	for _, in := range inputs {
		if err := processInput(cfg, in, opts, stdout); err != nil {
			return err
		}
	}
	return nil
}

type inputFile struct {
	stdin  bool
	path   string // path to read from
	rel    string // path relative to the glob base (used for hashing)
	output string // resolved output file ("" for stdout)
	data   []byte
}

func resolveInputs(cfg *config, stdin *os.File) ([]*inputFile, error) {
	if !cfg.input.isSet {
		info, err := stdin.Stat()
		if err != nil || info.Mode()&os.ModeCharDevice != 0 {
			return nil, newErr(hintCLI, "the html input should be piped into the cli")
		}
		return []*inputFile{{stdin: true}}, nil
	}
	raw := cfg.input.value
	cleaned := filepath.Clean(raw)
	switch filepath.Base(cleaned) {
	case ".", "..", string(filepath.Separator):
		return []*inputFile{{path: cleaned, rel: cleaned}}, nil
	}
	matches, err := glob.Glob(filepath.ToSlash(cleaned))
	if err != nil {
		return nil, err
	}
	if len(matches) == 0 {
		if info, err := os.Stat(raw); err == nil && info.IsDir() {
			return nil, newErr(hintGlob, "input path %q is a directory, not a file", raw)
		}
		return nil, newErr(hintGlob, "no files found matching pattern %q", raw)
	}
	out := make([]*inputFile, 0, len(matches))
	for _, m := range matches {
		out = append(out, &inputFile{path: m.Path, rel: m.Rel})
	}
	return out, nil
}

func isDirPath(p string) bool {
	return strings.HasSuffix(p, "/") || strings.HasSuffix(p, string(filepath.Separator))
}

func checkOutput(cfg *config, inputs []*inputFile) error {
	if !cfg.output.isSet {
		if len(inputs) > 1 {
			return newErr(hintGlob, "when processing multiple input files --output needs to be a directory")
		}
		return nil
	}
	output := cfg.output.value
	if isDirPath(output) {
		seen := map[string]bool{}
		for _, in := range inputs {
			name := "output"
			if !in.stdin {
				base := filepath.Base(in.path)
				name = strings.TrimSuffix(base, filepath.Ext(base))
			}
			fileName := name + ".md"
			if seen[fileName] {
				sum := sha256.Sum256([]byte(in.rel))
				fileName = name + "." + hex.EncodeToString(sum[:])[:10] + ".md"
			} else {
				seen[fileName] = true
			}
			in.output = filepath.Join(output, fileName)
		}
		return nil
	}
	base := filepath.Base(output)
	if len(inputs) > 1 {
		return fmt.Errorf("when processing multiple input files, --output %q must end with %q to indicate a directory", base, base+"/")
	}
	if info, err := os.Stat(output); err == nil && info.IsDir() {
		return newErr(hintOutputDir, "path %q exists and is a directory, did you mean %q?", base, base+"/")
	}
	inputs[0].output = output
	return nil
}

func processInput(cfg *config, in *inputFile, opts converter.Options, stdout io.Writer) error {
	var data []byte
	var err error
	if in.stdin {
		data, err = io.ReadAll(os.Stdin)
	} else {
		data, err = os.ReadFile(in.path)
	}
	if err != nil {
		return err
	}
	markdown, err := converter.Convert(data, opts)
	if err != nil {
		return err
	}
	if in.output == "" {
		_, err := fmt.Fprintf(stdout, "%s\n", markdown)
		return err
	}
	if !cfg.outputOverwrite {
		if _, err := os.Stat(in.output); err == nil {
			return fmt.Errorf("output path %q already exists. Use --output-overwrite to replace existing files", cfg.output.value)
		}
	}
	dir := filepath.Dir(in.output)
	if isDirPath(cfg.output.value) {
		dir = cfg.output.value
	}
	if err := os.MkdirAll(dir, os.ModePerm); err != nil {
		return err
	}
	return os.WriteFile(in.output, []byte(markdown), 0644)
}
