package cli

import (
	"golang.org/x/net/html"
	"golang.org/x/net/html/atom"

	"html2markdown/internal/selector"
)

func matchesAny(n *html.Node, sels []selector.Selector) bool {
	for _, s := range sels {
		if s.Match(n) {
			return true
		}
	}
	return false
}

func collectMatches(root *html.Node, sels []selector.Selector) []*html.Node {
	var out []*html.Node
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode && matchesAny(n, sels) {
			out = append(out, n)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(root)
	return out
}

// filterDocument removes the excluded elements and (if include selectors are
// given) only keeps the included elements.
func filterDocument(doc *html.Node, exclude, include []selector.Selector) *html.Node {
	if len(exclude) > 0 {
		for _, n := range collectMatches(doc, exclude) {
			if n.Parent != nil {
				n.Parent.RemoveChild(n)
			}
		}
	}
	if len(include) == 0 {
		return doc
	}
	matches := collectMatches(doc, include)

	newDoc := &html.Node{Type: html.DocumentNode}
	htmlNode := &html.Node{Type: html.ElementNode, Data: "html", DataAtom: atom.Html}
	head := &html.Node{Type: html.ElementNode, Data: "head", DataAtom: atom.Head}
	body := &html.Node{Type: html.ElementNode, Data: "body", DataAtom: atom.Body}
	newDoc.AppendChild(htmlNode)
	htmlNode.AppendChild(head)
	htmlNode.AppendChild(body)
	for _, n := range matches {
		if n.Parent != nil {
			n.Parent.RemoveChild(n)
		}
		body.AppendChild(n)
	}
	return newDoc
}
