package selector

import (
	"regexp"
	"strings"

	"golang.org/x/net/html"
)

type selectorGroup []Selector

func (g selectorGroup) Match(n *html.Node) bool {
	for _, s := range g {
		if s.Match(n) {
			return true
		}
	}
	return false
}

type tagSelector struct {
	tag string
}

func (s tagSelector) Match(n *html.Node) bool {
	return n.Type == html.ElementNode && n.Data == s.tag
}

type compoundSelector struct {
	selectors []Selector
}

func (s compoundSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	for _, sel := range s.selectors {
		if !sel.Match(n) {
			return false
		}
	}
	return true
}

type attrSelector struct {
	key, val    string
	operation   string
	regexp      *regexp.Regexp
	insensitive bool
}

func matchAttribute(n *html.Node, key string, f func(string) bool) bool {
	if n.Type != html.ElementNode {
		return false
	}
	for _, a := range n.Attr {
		if a.Key == key && f(a.Val) {
			return true
		}
	}
	return false
}

func matchInclude(val, s string, insensitive bool) bool {
	for s != "" {
		i := strings.IndexAny(s, " \t\r\n\f")
		if i == -1 {
			return equal(s, val, insensitive)
		}
		if equal(s[:i], val, insensitive) {
			return true
		}
		s = s[i+1:]
	}
	return false
}

func equal(a, b string, insensitive bool) bool {
	if insensitive {
		return strings.EqualFold(a, b)
	}
	return a == b
}

func hasPrefix(s, prefix string, insensitive bool) bool {
	if insensitive {
		return len(s) >= len(prefix) && strings.EqualFold(s[:len(prefix)], prefix)
	}
	return strings.HasPrefix(s, prefix)
}

func hasSuffix(s, suffix string, insensitive bool) bool {
	if insensitive {
		return len(s) >= len(suffix) && strings.EqualFold(s[len(s)-len(suffix):], suffix)
	}
	return strings.HasSuffix(s, suffix)
}

func (s attrSelector) Match(n *html.Node) bool {
	key, val := s.key, s.val
	switch s.operation {
	case "":
		return matchAttribute(n, key, func(string) bool { return true })
	case "=":
		return matchAttribute(n, key, func(v string) bool { return equal(v, val, s.insensitive) })
	case "!=":
		if n.Type != html.ElementNode {
			return false
		}
		for _, a := range n.Attr {
			if a.Key == key && equal(a.Val, val, s.insensitive) {
				return false
			}
		}
		return true
	case "~=":
		return matchAttribute(n, key, func(v string) bool { return matchInclude(val, v, s.insensitive) })
	case "|=":
		return matchAttribute(n, key, func(v string) bool {
			if !hasPrefix(v, val, s.insensitive) {
				return false
			}
			return len(v) == len(val) || v[len(val)] == '-'
		})
	case "^=":
		return matchAttribute(n, key, func(v string) bool {
			return val != "" && hasPrefix(v, val, s.insensitive)
		})
	case "$=":
		return matchAttribute(n, key, func(v string) bool {
			return val != "" && hasSuffix(v, val, s.insensitive)
		})
	case "*=":
		return matchAttribute(n, key, func(v string) bool {
			if val == "" {
				return false
			}
			if s.insensitive {
				return strings.Contains(strings.ToLower(v), strings.ToLower(val))
			}
			return strings.Contains(v, val)
		})
	case "#=":
		return matchAttribute(n, key, func(v string) bool { return s.regexp.MatchString(v) })
	}
	return false
}

type relativeSelector struct {
	name  string
	match Selector
}

func (s relativeSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	switch s.name {
	case "not":
		return !s.match.Match(n)
	case "has":
		return hasDescendantMatch(n, s.match)
	case "haschild":
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.ElementNode && s.match.Match(c) {
				return true
			}
		}
	}
	return false
}

func hasDescendantMatch(n *html.Node, sel Selector) bool {
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.ElementNode && (sel.Match(c) || hasDescendantMatch(c, sel)) {
			return true
		}
	}
	return false
}

func nodeText(n *html.Node) string {
	var b strings.Builder
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.TextNode {
			b.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(n)
	return b.String()
}

func nodeOwnText(n *html.Node) string {
	var b strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.TextNode {
			b.WriteString(c.Data)
		}
	}
	return b.String()
}

type containsSelector struct {
	own   bool
	value string
}

func (s containsSelector) Match(n *html.Node) bool {
	var text string
	if s.own {
		text = nodeOwnText(n)
	} else {
		text = nodeText(n)
	}
	return strings.Contains(strings.ToLower(text), s.value)
}

type regexpSelector struct {
	own    bool
	regexp *regexp.Regexp
}

func (s regexpSelector) Match(n *html.Node) bool {
	var text string
	if s.own {
		text = nodeOwnText(n)
	} else {
		text = nodeText(n)
	}
	return s.regexp.MatchString(text)
}

type nthSelector struct {
	a, b         int
	last, ofType bool
}

func (s nthSelector) Match(n *html.Node) bool {
	if s.a == 0 {
		if s.last {
			return simpleNthLastChildMatch(s.b, s.ofType, n)
		}
		return simpleNthChildMatch(s.b, s.ofType, n)
	}
	return nthChildMatch(s.a, s.b, s.last, s.ofType, n)
}

func nthChildMatch(a, b int, last, ofType bool, n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	parent := n.Parent
	if parent == nil || parent.Type == html.DocumentNode {
		return false
	}
	i := -1
	count := 0
	for c := parent.FirstChild; c != nil; c = c.NextSibling {
		if c.Type != html.ElementNode || (ofType && c.Data != n.Data) {
			continue
		}
		count++
		if c == n {
			i = count
			if !last {
				break
			}
		}
	}
	if i == -1 {
		return false
	}
	if last {
		i = count - i + 1
	}
	i -= b
	if a == 0 {
		return i == 0
	}
	return i%a == 0 && i/a >= 0
}

func simpleNthChildMatch(b int, ofType bool, n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	parent := n.Parent
	if parent == nil || parent.Type == html.DocumentNode {
		return false
	}
	count := 0
	for c := parent.FirstChild; c != nil; c = c.NextSibling {
		if c.Type != html.ElementNode || (ofType && c.Data != n.Data) {
			continue
		}
		count++
		if c == n {
			return count == b
		}
		if count >= b {
			return false
		}
	}
	return false
}

func simpleNthLastChildMatch(b int, ofType bool, n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	parent := n.Parent
	if parent == nil || parent.Type == html.DocumentNode {
		return false
	}
	count := 0
	for c := parent.LastChild; c != nil; c = c.PrevSibling {
		if c.Type != html.ElementNode || (ofType && c.Data != n.Data) {
			continue
		}
		count++
		if c == n {
			return count == b
		}
		if count >= b {
			return false
		}
	}
	return false
}

type onlyChildSelector struct {
	ofType bool
}

func (s onlyChildSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	parent := n.Parent
	if parent == nil || parent.Type == html.DocumentNode {
		return false
	}
	count := 0
	for c := parent.FirstChild; c != nil; c = c.NextSibling {
		if c.Type != html.ElementNode || (s.ofType && c.Data != n.Data) {
			continue
		}
		count++
		if count > 1 {
			return false
		}
	}
	return count == 1
}

type inputSelector struct{}

func (inputSelector) Match(n *html.Node) bool {
	return n.Type == html.ElementNode && (n.Data == "input" || n.Data == "select" || n.Data == "textarea" || n.Data == "button")
}

type emptySelector struct{}

func (emptySelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		switch c.Type {
		case html.ElementNode:
			return false
		case html.TextNode:
			if strings.TrimSpace(c.Data) != "" {
				return false
			}
		}
	}
	return true
}

type rootSelector struct{}

func (rootSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	if n.Parent == nil {
		return false
	}
	return n.Parent.Type == html.DocumentNode
}

type linkSelector struct{}

func (linkSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	if n.Data != "a" && n.Data != "area" && n.Data != "link" {
		return false
	}
	for _, a := range n.Attr {
		if a.Key == "href" {
			return true
		}
	}
	return false
}

type langSelector struct {
	lang string
}

func (s langSelector) Match(n *html.Node) bool {
	own := matchAttribute(n, "lang", func(val string) bool {
		val = strings.ToLower(val)
		return val == s.lang || strings.HasPrefix(val, s.lang+"-")
	})
	if n.Parent == nil {
		return own
	}
	return own || s.Match(n.Parent)
}

type enabledSelector struct{}

func (enabledSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	switch n.Data {
	case "a", "area", "link":
		return hasAttr(n, "href")
	case "optgroup", "menuitem", "fieldset":
		return !hasAttr(n, "disabled")
	case "button", "input", "select", "textarea", "option":
		return !hasAttr(n, "disabled") && !inDisabledFieldset(n)
	}
	return false
}

type disabledSelector struct{}

func (disabledSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	switch n.Data {
	case "optgroup", "menuitem", "fieldset":
		return hasAttr(n, "disabled")
	case "button", "input", "select", "textarea", "option":
		return hasAttr(n, "disabled") || inDisabledFieldset(n)
	}
	return false
}

func hasAttr(n *html.Node, key string) bool {
	for _, a := range n.Attr {
		if a.Key == key {
			return true
		}
	}
	return false
}

func inDisabledFieldset(n *html.Node) bool {
	if n.Parent == nil {
		return false
	}
	if n.Parent.Type == html.ElementNode && n.Parent.Data == "fieldset" && hasAttr(n.Parent, "disabled") &&
