	}
	return false
}

type neverSelector struct{}

func (neverSelector) Match(*html.Node) bool { return false }

type combinedSelector struct {
	first      Selector
	combinator byte
	second     Selector
}

func (s combinedSelector) Match(n *html.Node) bool {
	if s.first == nil {
