		for c := n.FirstChild; c != nil && !found; c = c.NextSibling {
			if isOriginalElement(c, atom.Table) {
				found = true
				return
			}
			walk(c)
		}
	}
	walk(table)
	return found
}

func spanValue(n *html.Node, key string) int {
	v, ok := getAttr(n, key)
	if !ok {
		return 1
	}
	num, err := strconv.Atoi(v)
	if err != nil || num < 1 {
		return 1
	}
	return num
}

func cellAlignment(n *html.Node) string {
	switch attrVal(n, "align") {
	case "left":
		return "left"
	case "center":
		return "center"
	case "right":
		return "right"
	}
	return ""
}

