		if c.opt.Table.NewlineBehavior != "preserve" {
			return "", false
		}
		content = strings.ReplaceAll(content, "\n", "<br />")
	}
	return content, true
}

func (c *conv) renderTable(w *strings.Builder, n *html.Node) bool {
	opt := c.opt.Table
	if !opt.PresentationTables && attrVal(n, "role") == "presentation" {
		return false
	}
	if hasNestedTable(n) {
		return false
	}
	trs := tableRows(n)

	type gridCell struct {
		set     bool
		content string
	}
	var grid [][]gridCell
	ensure := func(r, col int) {
		for len(grid) <= r {
			grid = append(grid, nil)
		}
		for len(grid[r]) <= col {
			grid[r] = append(grid[r], gridCell{})
		}
	}
	mirror := opt.SpanCellBehavior == "mirror"

	headerIndex := -1
	totalCells := 0
	for r, tr := range trs {
		ensure(r, -1)
		col := 0
		for _, td := range rowCells(tr) {
			if td.DataAtom == atom.Th && headerIndex == -1 {
				headerIndex = r
			}
			totalCells++
			content, ok := c.renderCellContent(td)
			if !ok {
				return false
			}
			for col < len(grid[r]) && grid[r][col].set {
				col++
			}
			colspan := spanValue(td, "colspan")
			rowspan := spanValue(td, "rowspan")
			for dr := 0; dr < rowspan; dr++ {
				for dc := 0; dc < colspan; dc++ {
					ensure(r+dr, col+dc)
					if grid[r+dr][col+dc].set {
						continue
					}
					val := ""
					if (dr == 0 && dc == 0) || mirror {
						val = content
					}
					grid[r+dr][col+dc] = gridCell{set: true, content: val}
				}
			}
			col += colspan
		}
	}
	if totalCells == 0 {
		return false
	}

	numCols := 0
	for _, row := range grid {
		if len(row) > numCols {
			numCols = len(row)
		}
	}
	rows := make([][]string, len(grid))
	for i, row := range grid {
		rows[i] = make([]string, numCols)
		for j, cell := range row {
			rows[i][j] = cell.content
		}
	}

	var alignRow *html.Node
	var header []string
	if headerIndex != -1 {
		header = rows[headerIndex]
		rows = append(rows[:headerIndex:headerIndex], rows[headerIndex+1:]...)
		alignRow = trs[headerIndex]
	} else if len(trs) > 0 {
		alignRow = trs[0]
	}
	if opt.SkipEmptyRows {
		filtered := rows[:0:0]
		for _, row := range rows {
			empty := true
			for _, cell := range row {
				if cell != "" {
					empty = false
					break
				}
			}
			if !empty {
				filtered = append(filtered, row)
			}
		}
		rows = filtered
	}
	if header == nil {
		if opt.HeaderPromotion && len(rows) > 0 {
			header = rows[0]
			rows = rows[1:]
		} else {
			header = make([]string, numCols)
		}
	}

	var aligns []string
	if alignRow != nil {
		for _, td := range rowCells(alignRow) {
			aligns = append(aligns, cellAlignment(td))
		}
	}

	widths := make([]int, numCols)
	for i := range widths {
		widths[i] = 1
	}
	measure := func(row []string) {
		for i, cell := range row {
			if l := utf8.RuneCountInString(cell); l > widths[i] {
				widths[i] = l
			}
		}
	}
	measure(header)
	for _, row := range rows {
		measure(row)
	}

	var b strings.Builder
	writeRow := func(row []string) {
		b.WriteString("|")
		for i, cell := range row {
			switch opt.CellPadding {
			case "minimal":
				b.WriteString(" " + cell + " |")
			case "none":
				b.WriteString(cell + "|")
			default:
				b.WriteString(" " + cell + strings.Repeat(" ", widths[i]-utf8.RuneCountInString(cell)) + " |")
			}
		}
	}
	writeRow(header)
	b.WriteString("\n|")
	for i := 0; i < numCols; i++ {
		align := ""
		if i < len(aligns) {
			align = aligns[i]
		}
		size := 3
		if opt.CellPadding != "minimal" && opt.CellPadding != "none" {
			size = widths[i] + 2
		}
		switch align {
		case "left":
			b.WriteString(":" + strings.Repeat("-", size-1))
		case "center":
			b.WriteString(":" + strings.Repeat("-", size-2) + ":")
		case "right":
			b.WriteString(strings.Repeat("-", size-1) + ":")
		default:
			b.WriteString(strings.Repeat("-", size))
		}
		b.WriteString("|")
	}
	for _, row := range rows {
		b.WriteString("\n")
		writeRow(row)
	}

	w.WriteString("\n\n")
	w.WriteString(b.String())
	w.WriteString("\n\n")

	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		if isOriginalElement(ch, atom.Caption) {
			w.WriteString("\n\n")
			c.renderChildren(w, ch)
			w.WriteString("\n\n")
		}
	}
	return true
}
