// adjacentText reports whether the node is directly preceded (or followed)
// by text that does not end (or start) with a space.
func adjacentText(n *html.Node, before bool) bool {
	m := n
	for {
		var sib *html.Node
		if before {
			sib = m.PrevSibling
		} else {
			sib = m.NextSibling
