			}
			if before {
				return !strings.HasSuffix(sib.Data, " ")
			}
			return !strings.HasPrefix(sib.Data, " ")
		}
		m = m.Parent
		if m == nil || m.Type != html.ElementNode || isBlockNode(m) {
