func writeDelimited(w *strings.Builder, content string, delim string, spaceBefore, spaceAfter bool) {
	if content == "" {
		return
	}
	if isBlankString(content) {
		w.WriteString(content)
		return
	}
	lines := strings.Split(content, "\\n")
	for i, line := range lines {
		if i > 0 {
