			lead = " "
		}
		if i == len(lines)-1 && spaceAfter && trail == "" && strings.HasSuffix(mid, "`") {
			trail = " "
		}
		w.WriteString(lead)
		w.WriteString(delim)
		w.WriteString(mid)
		w.WriteString(delim)
		w.WriteString(trail)
	}
